(function(){
var s=api.state||{},p=s.preferences||{};
var id=String(s.currentChannelID||""),name=String(s.currentChannel||"");
var cat=String(p.surfCategory||""),source=String(s.surfSource||"");
if(!/^[a-f0-9]{32}$/.test(id)){return "Spanish: no current channel";}
if(source==="malay"||cat==="Movies & Series"){return "Spanish: English source only";}
if(s.surfing!==true){return "Spanish: Surf is not active";}
if(s.currentSharedTransport===true||s.surfRotationControllable===false){return "Spanish: device-owned rotation required";}
var nonce=Date.now().toString(36)+"-"+Math.random().toString(36).slice(2,10);
var payload={schemaVersion:1,action:"add",channelID:id,channelName:name,nonce:nonce};
api.command("ui_set_value",{key:"spanishRequest",value:JSON.stringify(payload)});
api.command("refresh_catalogue",{});
api.command("next_channel",{});
api.log("Spanish mark requested: "+id);
return "Spanish: marked "+name+"; excluding and advancing";
})()

(function(){
var s=api.state||{},p=s.preferences||{};
var id=String(s.currentChannelID||""),name=String(s.currentChannel||"");
var cat=String(p.surfCategory||""),source=String(s.surfSource||"");
