if(source==="malay"||cat==="Movies & Series"){return "Spanish: English source only";}
var nonce=Date.now().toString(36)+"-"+Math.random().toString(36).slice(2,10);
var payload={schemaVersion:1,action:"remove",channelID:id,channelName:name,nonce:nonce};
api.command("ui_set_value",{key:"spanishRequest",value:JSON.stringify(payload)});
api.command("refresh_catalogue",{});
api.log("Spanish unmark requested: "+id);
return "Spanish: unmarked "+name+"; English membership will refresh";
})()

(function(){
var s=api.state||{};
var id=String(s.currentChannelID||""),name=String(s.currentChannel||"");
